import { expect, expectStatus, sample, test, uniqueName } from "../../fixtures";

test.describe("manage vendors", () => {
  // QA lead note (2026-11-02): this endpoint is being rewritten. Keep as fixme until PLAT-412 lands.
  test.fixme("a vendor under review cannot be edited", { tag: "@VEN-09" }, async ({ apiAs }) => {
    // Arrange: a member creates a vendor and submits it, moving it to "in_review".
    const member = await apiAs("member");
    const created = await expectStatus(
      await member.post("/api/vendors", {
        data: {
          name: uniqueName("VEN-09 Acme Freight"),
          category: "logistics",
          contact_email: "ops@acmefreight-ven09.example",
        },
      }),
      201,
    );

    await expectStatus(await member.post(`/api/vendors/${created.id}/submit`), 200);

    // Act: attempt to change the contact email while under review.
    const response = await member.patch(`/api/vendors/${created.id}`, {
      data: { contact_email: "billing@acmefreight.example" },
    });

    // Assert
    const body = await expectStatus(response, 409);
    expect(body.error.code).toBe("vendor_locked");
  });
});
